CREATE VIEW Gen_Producto_Totales AS SELECT p.IdProducto,a.IdAlmacen,COALESCE(SUM(x.TotalCompras),0) TotalCompras,COALESCE(SUM(x.TotalVentas),0) TotalVentas FROM Gen_Producto p CROSS JOIN Lo_Almacen a LEFT JOIN (SELECT d.IdProducto IdProducto,m.IdAlmacenDestino IdAlmacen,d.Cantidad TotalCompras,0 TotalVentas FROM Lo_Movimiento m JOIN Lo_MovimientoDetalle d ON d.hashMovimiento=m.Hash JOIN Lo_MovimientoTipo mt ON mt.IdMovimientoTipo=m.IdMovimientoTipo WHERE m.Anulado=0 AND mt.VaRegCompra=1 AND m.MovimientoFecha<=NOW() UNION ALL SELECT d.IdProducto,m.IdAlmacenOrigen,0,CASE WHEN mt.CodSunat='07' AND COALESCE(m.NotaIdMotivo,'') NOT IN ('01','02','06','07') THEN 0 ELSE d.Cantidad END FROM Lo_Movimiento m JOIN Lo_MovimientoDetalle d ON d.hashMovimiento=m.Hash JOIN Lo_MovimientoTipo mt ON mt.IdMovimientoTipo=m.IdMovimientoTipo WHERE m.Anulado=0 AND mt.VaRegCompra=1 AND m.MovimientoFecha<=NOW() UNION ALL SELECT d.IdProducto,v.IdAlmacen,0,CASE WHEN td.CodSunat='07' THEN CASE WHEN v.NotaIdMotivo IN ('01','02','06','07') THEN -(d.Cantidad) ELSE 0 END ELSE d.Cantidad END FROM Ve_DocVenta v JOIN Ve_DocVentaDet d ON d.IdDocVenta=v.idDocVenta JOIN Ve_DocVentaTipoDoc td ON td.IdTipoDoc=v.IdTipoDoc WHERE v.Anulado=0 AND td.VaRegVenta=1 AND v.FechaDoc<=NOW() UNION ALL SELECT pd.IdProductoDet IdProducto,m.IdAlmacenDestino IdAlmacen,d.Cantidad*pd.Cantidad TotalCompras,0 TotalVentas FROM Lo_Movimiento m JOIN Lo_MovimientoDetalle d ON d.hashMovimiento=m.Hash JOIN Lo_MovimientoTipo mt ON mt.IdMovimientoTipo=m.IdMovimientoTipo JOIN Gen_ProductoDet pd ON pd.IdProducto=d.IdProducto WHERE m.Anulado=0 AND mt.VaRegCompra=1 AND m.MovimientoFecha<=NOW() UNION ALL SELECT pd.IdProductoDet,m.IdAlmacenOrigen,0,CASE WHEN mt.CodSunat='07' AND COALESCE(m.NotaIdMotivo,'') NOT IN ('01','02','06','07') THEN 0 ELSE d.Cantidad*pd.Cantidad END FROM Lo_Movimiento m JOIN Lo_MovimientoDetalle d ON d.hashMovimiento=m.Hash JOIN Lo_MovimientoTipo mt ON mt.IdMovimientoTipo=m.IdMovimientoTipo JOIN Gen_ProductoDet pd ON pd.IdProducto=d.IdProducto WHERE m.Anulado=0 AND mt.VaRegCompra=1 AND m.MovimientoFecha<=NOW() UNION ALL SELECT pd.IdProductoDet,v.IdAlmacen,0,CASE WHEN td.CodSunat='07' THEN CASE WHEN v.NotaIdMotivo IN ('01','02','06','07') THEN -(d.Cantidad*pd.Cantidad) ELSE 0 END ELSE d.Cantidad*pd.Cantidad END FROM Ve_DocVenta v JOIN Ve_DocVentaDet d ON d.IdDocVenta=v.idDocVenta JOIN Ve_DocVentaTipoDoc td ON td.IdTipoDoc=v.IdTipoDoc JOIN Gen_ProductoDet pd ON pd.IdProducto=d.IdProducto WHERE v.Anulado=0 AND td.VaRegVenta=1 AND v.FechaDoc<=NOW()) x ON x.IdProducto=p.IdProducto AND x.IdAlmacen=a.IdAlmacen GROUP BY p.IdProducto,a.IdAlmacen;